function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each value of nums is an integer from 1 to 1000.';
  if (!Number.isInteger(k) || k < 1 || k > 2000) return 'k is an integer from 1 to 2000.';
  return null;
}

