function twoSumLessThanK(nums, k) {
  nums.sort((a, b) => a - b);
  let left = 0;
  let right = nums.length - 1;
  let best = -1;

  while (left < right) {
    const sum = nums[left] + nums[right];
    if (sum < k) {
      best = Math.max(best, sum);
      left++;
    } else {
      right--;
    }
  }
  return best;
}

