function twoSumLessThanK(nums, k) {
  let answer = -1;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      const total = nums[i] + nums[j];
      if (total < k && total > answer) answer = total;
    }
  }
  return answer;
}

