function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const nums = Array.from({ length: 100 }, () => int(1, 1000));
    return [nums, int(1, 2000)];
  }
  const n = int(1, 8);
  const top = rand() < 0.5 ? 10 : 40;
  const nums = Array.from({ length: n }, () => int(1, top));
  return [nums, int(1, 2 * top + 2)];
}
